import {defineComponent,h,ref} from 'vue';
export const YkSidebar=defineComponent({name:'YkSidebar',props:{items:{type:Array,default:()=>[]},modelValue:String,brand:{type:String,default:'工作空间'},collapsed:{type:Boolean,default:undefined}},emits:['update:modelValue','update:collapsed'],setup(p,{emit,slots}){const local=ref(false);return()=>{const collapsed=p.collapsed===undefined?local.value:p.collapsed;return h('aside',{class:['yk-sidebar',{'is-collapsed':collapsed}],'aria-label':p.brand},[h('div',{class:'yk-sidebar__head'},[!collapsed?h('strong',{},p.brand):null,h('button',{type:'button','aria-label':collapsed?'展开侧栏':'收起侧栏','aria-expanded':!collapsed,onClick:()=>{local.value=!collapsed;emit('update:collapsed',!collapsed);}},collapsed?'›':'‹')]),h('nav',{'aria-label':p.brand+'导航'},p.items.map((item,i)=>h('button',{type:'button',disabled:item.disabled,'aria-current':p.modelValue===item.value?'page':undefined,title:collapsed?item.label:undefined,'aria-label':item.label,onClick:()=>emit('update:modelValue',item.value)},[h('span',{class:'yk-sidebar__icon','aria-hidden':'true'},String(i+1).padStart(2,'0')),!collapsed?h('span',{},item.label):null]))),slots.footer?.()]);};}});
